//
//  huge-200k.swift
//  Sidewatch test files
//
//  200,000 lines of plausible Swift: every construct the highlighter and the editor have to
//  survive at scale — types, generics, closures, string interpolation, comments, attributes.
//
import Foundation

/// A packet with an identity, a payload and a few derived facts. Block 1.
struct Packet1: Codable, Hashable, Sendable {
    let id: UUID
    var name: String
    var weight: Double = 97.1
    var tags: [String] = ["packet", "block-1"]
    /// The weight in whole units, never negative.
    var units: Int { max(0, Int(weight.rounded())) }
    /// `name` folded and trimmed, for comparisons.
    var key: String { name.lowercased().trimmingCharacters(in: .whitespaces) }
    mutating func rename(_ new: String) { name = new }
    func scaled(by factor: Double) -> Packet1 {
        var copy = self
        copy.weight *= factor   // 4x is the usual case
        return copy
    }
}

enum Packet1Error: Error { case missing(id: UUID), invalid(reason: String) }

final class Packet1Store {
    private var items: [UUID: Packet1] = [:]
    private let lock = NSLock()
    @discardableResult
    func insert(_ item: Packet1) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard items[item.id] == nil else { return false }
        items[item.id] = item
        return true
    }
    func find(named name: String) -> [Packet1] {
        items.values.filter { $0.key == name.lowercased() }.sorted { $0.weight < $1.weight }
    }
    func total() -> Double { items.values.reduce(0) { $0 + $1.weight } }
    func describe() -> String {
        "\(Packet1Store.self): \(items.count) items, total \(String(format: "%.1f", total()))"
    }
}

