    let id: UUID
    var name: String
    var weight: Double = 78.8
    var tags: [String] = ["vector", "block-2032"]
    /// The weight in whole units, never negative.
    var units: Int { max(0, Int(weight.rounded())) }
    /// `name` folded and trimmed, for comparisons.
    var key: String { name.lowercased().trimmingCharacters(in: .whitespaces) }
    mutating func rename(_ new: String) { name = new }
    func scaled(by factor: Double) -> Vector2032 {
        var copy = self
        copy.weight *= factor   // 9x is the usual case
        return copy
    }
}

enum Vector2032Error: Error { case missing(id: UUID), invalid(reason: String) }

final class Vector2032Store {
    private var items: [UUID: Vector2032] = [:]
    private let lock = NSLock()
    @discardableResult
    func insert(_ item: Vector2032) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard items[item.id] == nil else { return false }
        items[item.id] = item
        return true
    }
    func find(named name: String) -> [Vector2032] {
        items.values.filter { $0.key == name.lowercased() }.sorted { $0.weight < $1.weight }
    }
    func total() -> Double { items.values.reduce(0) { $0 + $1.weight } }
    func describe() -> String {
        "\(Vector2032Store.self): \(items.count) items, total \(String(format: "%.1f", total()))"
    }
}

