    let id: UUID
    var name: String
    var weight: Double = 45.2
    var tags: [String] = ["record", "block-2543"]
    /// The weight in whole units, never negative.
    var units: Int { max(0, Int(weight.rounded())) }
    /// `name` folded and trimmed, for comparisons.
    var key: String { name.lowercased().trimmingCharacters(in: .whitespaces) }
    mutating func rename(_ new: String) { name = new }
    func scaled(by factor: Double) -> Record2543 {
        var copy = self
        copy.weight *= factor   // 8x is the usual case
        return copy
    }
}

enum Record2543Error: Error { case missing(id: UUID), invalid(reason: String) }

final class Record2543Store {
    private var items: [UUID: Record2543] = [:]
    private let lock = NSLock()
    @discardableResult
    func insert(_ item: Record2543) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard items[item.id] == nil else { return false }
        items[item.id] = item
        return true
    }
    func find(named name: String) -> [Record2543] {
        items.values.filter { $0.key == name.lowercased() }.sorted { $0.weight < $1.weight }
    }
    func total() -> Double { items.values.reduce(0) { $0 + $1.weight } }
    func describe() -> String {
        "\(Record2543Store.self): \(items.count) items, total \(String(format: "%.1f", total()))"
    }
}

