    var name: String
    var weight: Double = 70.7
    var tags: [String] = ["packet", "block-3202"]
    /// The weight in whole units, never negative.
    var units: Int { max(0, Int(weight.rounded())) }
    /// `name` folded and trimmed, for comparisons.
    var key: String { name.lowercased().trimmingCharacters(in: .whitespaces) }
    mutating func rename(_ new: String) { name = new }
    func scaled(by factor: Double) -> Packet3202 {
        var copy = self
        copy.weight *= factor   // 2x is the usual case
        return copy
    }
}

enum Packet3202Error: Error { case missing(id: UUID), invalid(reason: String) }

final class Packet3202Store {
    private var items: [UUID: Packet3202] = [:]
    private let lock = NSLock()
    @discardableResult
    func insert(_ item: Packet3202) -> Bool {
        lock.lock(); defer { lock.unlock() }
        guard items[item.id] == nil else { return false }
        items[item.id] = item
        return true
    }
    func find(named name: String) -> [Packet3202] {
        items.values.filter { $0.key == name.lowercased() }.sorted { $0.weight < $1.weight }
    }
    func total() -> Double { items.values.reduce(0) { $0 + $1.weight } }
    func describe() -> String {
        "\(Packet3202Store.self): \(items.count) items, total \(String(format: "%.1f", total()))"
    }
}

